console.log(result);

class Wallet {
  #balance = 0;
  static #count = 0;

  constructor(owner) {
    this.owner = owner;
    Wallet.#count++;
  }

  deposit(amount) {
    this.#balance += amount;
    return this;
  }

  get balance() {
    return this.#balance;
  }

  static isWallet(obj) {
    return #balance in obj;
  }

  static get count() {
    return Wallet.#count;
  }
}

const w = new Wallet('Nadia').deposit(500).deposit(250);
console.log(w.balance, w['#balance'], Object.keys(w), Wallet.isWallet({ balance: 750 }), Wallet.count);
